preguntas.circuito:
* Ejercicio 24.9: paso bajo RC
Vin in 0 DC 0 AC 1
R1 in out {R}
C1 out 0 {C}

preguntas.control:
ac dec 200 1 1meg
let gdb = db(v(out))
meas ac fc WHEN gdb=-3.0103 FALL=1

preguntas.circuito:
* Ejercicio 24.10: paso alto RC (bloqueo de continua)
Vin in 0 DC 0 AC 1
C1 in out {C}
R1 out 0 {R}

preguntas.control:
ac dec 200 0.1 100k
let gdb = db(v(out))
meas ac fc WHEN gdb=-3.0103 RISE=1

preguntas.circuito:
* Ejercicio 24.11: Sallen-Key paso bajo de ganancia unidad (figura 24.7)
Vin in 0 DC 0 AC 1
R1 in a {R}
R2 a b {R}
C2 b 0 {C2}
C1 a out {C1}
* operacional: ganancia 1e5, polo a 10 Hz (GBW = 1 MHz), 100 ohm de salida
Eamp n1 0 b out 1e5
Rp n1 n2 1k
Cp n2 0 15.915u
Ebuf n3 0 n2 0 1
Ro n3 out 100

preguntas.control:
ac dec 200 10 1meg
let gdb = db(v(out))
let gmag = mag(v(out))
let fase = 180/pi*cph(v(out))
meas ac fc WHEN gdb=-3.0103 FALL=1
meas ac q FIND gmag WHEN fase=-90
